<?php require_once 'includes/config.php'; requireUser(); if($_SERVER['REQUEST_METHOD']!=='POST')redirect('report_incident.php'); verifyCsrf(); $category=trim($_POST['category']??'');$description=trim($_POST['description']??'');$valid=['Electricity','Water','Cleaning','Internet','Other']; if(!in_array($category,$valid,true)||$description===''||strlen($description)>2000){$_SESSION['old_complaint']=['category'=>$category,'description'=>$description];flash('error','Please select a category and enter a description up to 2000 characters.');redirect('report_incident.php');}$s=$conn->prepare('INSERT INTO complaints(user_id,category,description) VALUES(?,?,?)');$s->bind_param('iss',$_SESSION['user_id'],$category,$description);if($s->execute())flash('success','Complaint #'.$conn->insert_id.' submitted successfully.');else flash('error','Could not submit the complaint. Please try again.');$s->close();redirect('user_dashboard.php');
